import {translations} from './i18n.mjs';
const strings={
rate:['Monthly interest rate (%)','Igipimo cy’inyungu cya buri kwezi (%)','Taux d’intérêt mensuel (%)'],loading:['Loading…','Birimo gufunguka…','Chargement…'],signIn:['Sign in','Injira','Se connecter'],register:['Create an account','Fungura konti','Créer un compte'],password:['Password','Ijambo ry’ibanga','Mot de passe'],passwordHint:['Use 12–128 characters and a unique password.','Koresha inyuguti 12–128 n’ijambo ry’ibanga ryihariye.','Utilisez 12 à 128 caractères et un mot de passe unique.'],authIntro:['Your savings group, connected.','Ikimina cyanyu, hamwe.','Votre groupe d’épargne, connecté.'],registerIntro:['Create an account, then create or join an ikimina.','Fungura konti, hanyuma ushinge cyangwa winjire mu kimina.','Créez un compte, puis créez ou rejoignez un ikimina.'],noAccount:['New to e-Kimina?','Ni ubwa mbere ukoresha e-Kimina?','Nouveau sur e-Kimina ?'],hasAccount:['Already have an account?','Usanzwe ufite konti?','Vous avez déjà un compte ?'],account:['Your account','Konti yawe','Votre compte'],logout:['Sign out','Sohoka','Se déconnecter'],yourGroups:['Your ibimina','Ibimina byawe','Vos ibimina'],createOrJoin:['Create or join a group','Shinga cyangwa winjire mu kimina','Créer ou rejoindre un groupe'],createGroup:['Create an ikimina','Shinga ikimina','Créer un ikimina'],joinGroup:['Join an ikimina','Injira mu kimina','Rejoindre un ikimina'],joinToken:['Invitation code','Kode y’ubutumire','Code d’invitation'],groupIntro:['Create your ikimina or use an invitation from its chairperson.','Shinga ikimina cyangwa ukoreshe ubutumire wahawe na perezida wacyo.','Créez votre ikimina ou utilisez une invitation de son président.'],createIntro:['You will be chairperson. Invite a treasurer to confirm payments.','Uzaba perezida. Tumira umubitsi uzemeza ubwishyu.','Vous serez président. Invitez un trésorier pour confirmer les paiements.'],inviteMember:['Invite a member','Tumira umunyamuryango','Inviter un membre'],inviteIntro:['Valid for 48 hours, once, for this phone number only. Share directly with the intended person.','Ubutumire bumara amasaha 48, bukoreshwa rimwe gusa n’ufite iyi nimero. Buhe uwo bugenewe.','Valable 48 heures, à usage unique, pour ce numéro uniquement. Transmettez au destinataire.'],inviteCreated:['Invitation created','Ubutumire bwateguwe','Invitation créée'],invitationCode:['Save this invitation code','Bika iyi kode y’ubutumire','Conservez ce code d’invitation'],inviteWarning:['Shown only once. Save it now. No SMS has been sent.','Igaragara rimwe gusa. Yibike ubu. Nta SMS yoherejwe.','Affiché une seule fois. Conservez-le. Aucun SMS envoyé.'],groupCreated:['Your ikimina is ready.','Ikimina cyawe cyashyizweho.','Votre ikimina est prêt.'],joinedGroup:['You joined the ikimina.','Winjiye mu kimina.','Vous avez rejoint l’ikimina.'],activeSessions:['Active sign-ins','Aho konti yawe yinjiye','Connexions actives'],currentSession:['This sign-in','Aha winjiriye','Cette connexion'],revoke:['Sign out this session','Sohora iyi konti aho yinjiye','Déconnecter cette session'],sessionRevoked:['Session signed out.','Konti yasohowe.','Session déconnectée.'],serverSaved:['Saved on the server','Byabitswe kuri seriveri','Enregistré sur le serveur'],serverSavedInfo:['Records are saved in the shared server database. Access follows group permissions.','Amakuru abikwa kuri seriveri. Agaragara hakurikijwe inshingano mu kimina.','Données conservées dans la base partagée. Accès selon les permissions.'],developmentNotice:['Development build · Phone verification and account recovery are not configured. Use test data only.','Urubuga ruracyubakwa · Kwemeza telefoni no kugarura konti ntibirashyirwaho. Koresha amakuru y’igerageza gusa.','Version de développement · Vérification du téléphone et récupération du compte non configurées. Données de test uniquement.'],refresh:['Refresh','Ongera urebe amakuru','Actualiser'],yourGroupOnline:['Your ikimina. Connected.','Ikimina cyawe kuri interineti.','Votre ikimina, connecté.'],connectionError:['Server unreachable. Check connection and retry. Financial commands can be retried safely.','Seriveri ntiyabonetse. Reba uko uhujwe wongere ugerageze. Igikorwa cy’amafaranga ntikibarwa kabiri.','Serveur inaccessible. Vérifiez la connexion et réessayez. Aucun double enregistrement financier.'],serverError:['The request could not be completed.','Iki gikorwa nticyarangiye.','La demande n’a pas pu être terminée.'],unauthorized:['Please sign in again.','Ongera winjire muri konti.','Veuillez vous reconnecter.'],invalidCredentials:['Phone number or password is incorrect.','Telefoni cyangwa ijambo ry’ibanga si byo.','Numéro ou mot de passe incorrect.'],accountUnavailable:['Account unavailable for registration. Try signing in.','Iyi konti ntishobora gufungurwa. Gerageza kwinjira.','Inscription indisponible. Essayez de vous connecter.'],passwordLength:['Use 12–128 characters.','Koresha inyuguti 12–128.','Utilisez 12 à 128 caractères.'],invalidInput:['Check the information and try again.','Reba amakuru wongere ugerageze.','Vérifiez les informations et réessayez.'],rateLimited:['Too many attempts. Try again in 15 minutes.','Wagerageje kenshi cyane. Ongera nyuma y’iminota 15.','Trop de tentatives. Réessayez dans 15 minutes.'],invalidInvite:['Invalid, expired, used, or intended for another phone number.','Ubutumire ntibwemewe, bwararangiye, bwarakoreshejwe cyangwa bugenewe indi nimero.','Invitation invalide, expirée, utilisée ou destinée à un autre numéro.'],alreadyMember:['You already belong to this ikimina.','Usanzwe uri muri iki kimina.','Vous faites déjà partie de cet ikimina.'],csrf:['Session changed. Refresh and retry.','Uburyo winjiyemo bwahindutse. Ongera ufungure.','Session modifiée. Actualisez et réessayez.'],invalidOrigin:['Open the configured server address.','Fungura aderesi ya seriveri yemewe.','Ouvrez l’adresse configurée du serveur.'],notFound:['Record not found.','Aya makuru ntiyabonetse.','Enregistrement introuvable.'],idempotencyConflict:['Request changed after submission. Refresh and check records before resubmitting.','Ubusabe bwahindutse nyuma yo koherezwa. Ongera urebe inyandiko.','Demande modifiée après soumission. Actualisez et vérifiez les écritures.'],idempotencyRequired:['Refresh the form and try again.','Ongera ufungure ifishi ugerageze.','Actualisez le formulaire et réessayez.'],bodyTooLarge:['Request too large.','Amakuru wohereje ni menshi cyane.','Demande trop volumineuse.'],groupCreatedEvent:['Group created','Ikimina cyashinzwe','Groupe créé'],invitationCreatedEvent:['Invitation created','Ubutumire bwateguwe','Invitation créée'],memberJoinedEvent:['Member joined','Umunyamuryango yinjiye','Membre inscrit'],tryDemo:['Get started','Tangira','Commencer'],demoWarning:['Development version — test data only.','Urubuga ruracyubakwa — amakuru y’igerageza gusa.','Version de développement — données de test uniquement.'],goalNote:['Only confirmed contributions count toward group savings.','Imisanzu yemejwe gusa ni yo ibarwa mu bwizigame.','Seules les cotisations confirmées comptent dans l’épargne.'],signInSuccess:['Signed in.','Winjiye muri konti.','Connexion réussie.'],logoutSuccess:['Signed out.','Wasohotse muri konti.','Déconnexion réussie.'],interestMethod:['Interest method','Uburyo bwo kubara inyungu','Méthode de calcul des intérêts'],flat:['Flat interest','Inyungu ku gishoro cyose','Intérêts forfaitaires'],reducing:['Reducing balance','Inyungu ku gishoro gisigaye','Capital restant dû'],allocation:['Repayments cover scheduled interest first, then principal. No early-payment discount in this development version.','Ubwishyu bubanza kwishyura inyungu ziteganyijwe, hanyuma igishoro. Iri gerageza ntirigabanya inyungu ku wishyuye mbere.','Les remboursements couvrent les intérêts prévus, puis le capital. Pas de remise pour remboursement anticipé dans cette version.'],settingsInfo:['New rules apply to new applications. Existing loans keep their terms. Reducing balance uses equal principal installments with monthly interest on the scheduled remaining principal.','Amategeko mashya areba ubusabe bushya. Inguzanyo zisanzwe zigumana amasezerano yazo. Inyungu ku gishoro gisigaye zibarwa buri kwezi, igishoro cyishyurwa mu bice bingana.','Les nouvelles règles concernent les nouvelles demandes. Les prêts existants conservent leurs conditions. Capital restant dû : capital amorti par parts égales, intérêts mensuels sur le solde prévu.'],loanInfo:['Flat: interest on the original principal each month. Reducing balance: equal principal installments and interest on scheduled remaining principal. Terms are fixed on application.','Ku gishoro cyose: inyungu zibarwa ku gishoro cya mbere buri kwezi. Ku gishoro gisigaye: igishoro cyishyurwa mu bice bingana, inyungu zikabarwa ku gisigaye. Amasezerano abikwa igihe usabye.','Forfaitaire : intérêts mensuels sur le capital initial. Dégressif : parts égales de capital, intérêts sur le solde prévu. Conditions figées à la demande.'],howText:['Pay outside e-Kimina, submit a notice, then wait for the treasurer to confirm receipt. Only approved payments update balances. Accounts and permissions are enforced on the server. This development build has no phone verification or account recovery: use test data only.','Ishyura hanze ya e-Kimina, menyesha ubwishyu, utegereze ko umubitsi yemeza ko yakiriye. Ubwishyu bwemejwe gusa ni bwo buhindura amafaranga yanditswe. Konti n’inshingano bigenzurwa na seriveri. Kwemeza telefoni no kugarura konti ntibirashyirwaho: koresha amakuru y’igerageza gusa.','Payez hors d’e-Kimina, déclarez le paiement, puis attendez la confirmation du trésorier. Seuls les paiements approuvés modifient les soldes. Comptes et permissions contrôlés sur le serveur. Vérification du téléphone et récupération non configurées : données de test uniquement.']};
for(const [key,values] of Object.entries(strings))['en','rw','fr'].forEach((l,i)=>translations[l][key]=values[i]);
